// tb_noc_hop_probes: NOC-2 isolated hop probes (I-3 / Track HP).
// Scaffold (mesh, six production NIs with the per-instance local port binding = the
// XSim assertion-sampling workaround, r_idle/l_idle probes) is COPIED verbatim from
// NOC_PQATTEST.srcs/sim_1/new/tb_noc_perf.sv lines 13-213 (generated by
// scripts/prepare_perf_bench.py from tb_noc_n81.sv); those files are not edited.
// Expected counts: reports/i3_hp/HP_COUNT_DERIVATION.md.
`timescale 1ns/1ps
module tb_noc_hop_probes #(
    parameter int W   = 64,
    parameter bit WDE = 1
);

    import noc_pkg::*;

    localparam int NT = 6;
    localparam int T_CPU0 = 0, T_CPU1 = 1, T_MEM = 2, T_CRY = 3, T_ROT = 4, T_SPF = 5;

    logic clk = 1'b0;
    logic rst;
    always #10 clk = ~clk;

    //-------------------------------------------------------------------------
    // Mesh
    //-------------------------------------------------------------------------
    flit_t [NT-1:0] m_in_flit;
    logic  [NT-1:0] m_in_valid, m_in_ready;
    flit_t [NT-1:0] m_out_flit;
    logic  [NT-1:0] m_out_valid, m_out_ready;

    noc_mesh_3x2 #(.LINK_PIPE(1'b1)) mesh (
        .clk, .rst,
        .tile_in_flit (m_in_flit),  .tile_in_valid (m_in_valid),  .tile_in_ready (m_in_ready),
        .tile_out_flit(m_out_flit), .tile_out_valid(m_out_valid), .tile_out_ready(m_out_ready)
    );

    //-------------------------------------------------------------------------
    // Tile <-> NI signals
    //-------------------------------------------------------------------------
    logic                    tx_valid   [NT], tx_ready [NT];
    coord_t                  tx_dest    [NT];
    msg_type_e               tx_msg     [NT];
    logic [10:0]             tx_control [NT];
    logic [FLIT_WIDTH-1:0]   tx_pdata   [NT];
    logic                    tx_pvalid  [NT], tx_pready [NT];
    logic [MAC_TAG_BITS-1:0] tx_mac     [NT];
    logic                    tx_error   [NT];

    coord_t                  rx_src [NT], rx_dst [NT];
    msg_type_e               rx_msg [NT];
    logic [10:0]             rx_ctl [NT];
    logic [4:0]              rx_len [NT];
    logic                    rx_hv  [NT];
    logic [FLIT_WIDTH-1:0]   rx_pd  [NT];
    logic                    rx_pv  [NT], rx_pl [NT];
    logic                    rx_ready [NT];
    logic [MAC_TAG_BITS-1:0] rx_mt  [NT];
    logic                    rx_mv  [NT], rx_perr [NT], rx_lerr [NT], rx_abort [NT];

    logic                    st_clr [NT];
    logic                    c_sticky [NT], f_sticky [NT];
    logic [7:0]              c_cnt [NT], f_cnt [NT];
    logic [9:0]              c_info [NT];
    logic                    tx_busy [NT], rx_busy [NT];

    // XSim workaround (2026-10-01): every NI port is bound to a per-instance LOCAL
    // variable, then copied to/from the TB arrays. Binding ports directly to
    // array/packed-bit selects made XSim concurrent assertions inside the NI sample
    // the wrong element (false a_tx_no_bubble / a_no_slot_blocks_mem_request).
    for (genvar g = 0; g < NT; g++) begin : GN
        logic l_tx_valid;
        logic l_tx_ready;
        coord_t l_tx_dest_coord;
        msg_type_e l_tx_msg_type;
        logic [10:0] l_tx_control;
        logic [FLIT_WIDTH-1:0] l_tx_payload_data;
        logic l_tx_payload_valid;
        logic l_tx_payload_ready;
        logic [MAC_TAG_BITS-1:0] l_tx_mac_tag;
        logic l_tx_error;
        flit_t l_noc_tx_flit;
        logic l_noc_tx_valid;
        logic l_noc_tx_ready;
        flit_t l_noc_rx_flit;
        logic l_noc_rx_valid;
        logic l_noc_rx_ready;
        coord_t l_rx_src_coord;
        coord_t l_rx_dest_coord;
        msg_type_e l_rx_msg_type;
        logic [10:0] l_rx_control;
        logic [4:0] l_rx_length;
        logic l_rx_head_valid;
        logic [FLIT_WIDTH-1:0] l_rx_payload_data;
        logic l_rx_payload_valid;
        logic l_rx_payload_last;
        logic l_rx_ready;
        logic [MAC_TAG_BITS-1:0] l_rx_mac_tag;
        logic l_rx_mac_valid;
        logic l_rx_protocol_error;
        logic l_rx_length_error;
        logic l_rx_abort;
        logic l_ni_status_clr;
        logic l_ni_contain_sticky;
        logic [7:0] l_ni_contain_cnt;
        logic [9:0] l_ni_contain_info;
        logic l_ni_framing_sticky;
        logic [7:0] l_ni_framing_cnt;
        logic l_tx_busy;
        logic l_rx_busy;
        assign l_tx_valid = tx_valid[g];
        assign tx_ready[g] = l_tx_ready;
        assign l_tx_dest_coord = tx_dest[g];
        assign l_tx_msg_type = tx_msg[g];
        assign l_tx_control = tx_control[g];
        assign l_tx_payload_data = tx_pdata[g];
        assign l_tx_payload_valid = tx_pvalid[g];
        assign tx_pready[g] = l_tx_payload_ready;
        assign l_tx_mac_tag = tx_mac[g];
        assign tx_error[g] = l_tx_error;
        assign m_in_flit[g] = l_noc_tx_flit;
        assign m_in_valid[g] = l_noc_tx_valid;
        assign l_noc_tx_ready = m_in_ready[g];
        assign l_noc_rx_flit = m_out_flit[g];
        assign l_noc_rx_valid = m_out_valid[g];
        assign m_out_ready[g] = l_noc_rx_ready;
        assign rx_src[g] = l_rx_src_coord;
        assign rx_dst[g] = l_rx_dest_coord;
        assign rx_msg[g] = l_rx_msg_type;
        assign rx_ctl[g] = l_rx_control;
        assign rx_len[g] = l_rx_length;
        assign rx_hv[g] = l_rx_head_valid;
        assign rx_pd[g] = l_rx_payload_data;
        assign rx_pv[g] = l_rx_payload_valid;
        assign rx_pl[g] = l_rx_payload_last;
        assign l_rx_ready = rx_ready[g];
        assign rx_mt[g] = l_rx_mac_tag;
        assign rx_mv[g] = l_rx_mac_valid;
        assign rx_perr[g] = l_rx_protocol_error;
        assign rx_lerr[g] = l_rx_length_error;
        assign rx_abort[g] = l_rx_abort;
        assign l_ni_status_clr = st_clr[g];
        assign c_sticky[g] = l_ni_contain_sticky;
        assign c_cnt[g] = l_ni_contain_cnt;
        assign c_info[g] = l_ni_contain_info;
        assign f_sticky[g] = l_ni_framing_sticky;
        assign f_cnt[g] = l_ni_framing_cnt;
        assign tx_busy[g] = l_tx_busy;
        assign rx_busy[g] = l_rx_busy;
        noc_network_interface #(
            .LOCAL_TILE_ID (g),
            .WD_ENABLE     (WDE),
            .WD_LIMIT      (W)
        ) ni (
            .clk, .rst,
            .tx_valid(l_tx_valid),
            .tx_ready(l_tx_ready),
            .tx_dest_coord(l_tx_dest_coord),
            .tx_msg_type(l_tx_msg_type),
            .tx_control(l_tx_control),
            .tx_payload_data(l_tx_payload_data),
            .tx_payload_valid(l_tx_payload_valid),
            .tx_payload_ready(l_tx_payload_ready),
            .tx_mac_tag(l_tx_mac_tag),
            .tx_error(l_tx_error),
            .noc_tx_flit(l_noc_tx_flit),
            .noc_tx_valid(l_noc_tx_valid),
            .noc_tx_ready(l_noc_tx_ready),
            .noc_rx_flit(l_noc_rx_flit),
            .noc_rx_valid(l_noc_rx_valid),
            .noc_rx_ready(l_noc_rx_ready),
            .rx_src_coord(l_rx_src_coord),
            .rx_dest_coord(l_rx_dest_coord),
            .rx_msg_type(l_rx_msg_type),
            .rx_control(l_rx_control),
            .rx_length(l_rx_length),
            .rx_head_valid(l_rx_head_valid),
            .rx_payload_data(l_rx_payload_data),
            .rx_payload_valid(l_rx_payload_valid),
            .rx_payload_last(l_rx_payload_last),
            .rx_ready(l_rx_ready),
            .rx_mac_tag(l_rx_mac_tag),
            .rx_mac_valid(l_rx_mac_valid),
            .rx_protocol_error(l_rx_protocol_error),
            .rx_length_error(l_rx_length_error),
            .rx_abort(l_rx_abort),
            .ni_status_clr(l_ni_status_clr),
            .ni_contain_sticky(l_ni_contain_sticky),
            .ni_contain_cnt(l_ni_contain_cnt),
            .ni_contain_info(l_ni_contain_info),
            .ni_framing_sticky(l_ni_framing_sticky),
            .ni_framing_cnt(l_ni_framing_cnt),
            .tx_busy(l_tx_busy),
            .rx_busy(l_rx_busy)
        );
    end

    logic r_idle [NT];
    logic l_idle [NT];

    for (genvar g = 0; g < NT; g++) begin : GP
        always_comb begin
            r_idle[g] = !mesh.GEN_R[g].r.eject_wr_q &&
                         mesh.GEN_R[g].r.eject_empty &&
                        (mesh.GEN_R[g].r.u_allocator.output_locked == '0);
            for (int i = 0; i < NUM_PORTS * NUM_VC; i++)
                if (!mesh.GEN_R[g].r.fifo_empty[i]) r_idle[g] = 1'b0;
            for (int p = 0; p < NUM_PORTS; p++)
                for (int v = 0; v < NUM_VC; v++)
                    if (int'(mesh.GEN_R[g].r.u_credit_control.credit_count[p][v]) != 4)
                        r_idle[g] = 1'b0;
            l_idle[g] = !(mesh.GEN_R[g].qv_n || mesh.GEN_R[g].qv_s ||
                          mesh.GEN_R[g].qv_e || mesh.GEN_R[g].qv_w);
        end
    end

    //=========================================================================
    // NOC-2 isolated hop probes (I-3 / Track HP, N-8 "isolated hop probes are a
    // separate subgate"). Counts: reports/i3_hp/HP_COUNT_DERIVATION.md.
    //
    // Production transport only (M-F1 rev 5): production NOC_PKG, production NI,
    // production mesh, no L2. MAC framing is selected by PQ_MAC_ON (NOC_PKG).
    //
    // For every ordered (a,b) tile pair, after a fresh reset:
    //   probe 1  VC0  MEM_WR_REQ        a -> b   (allocates NI slot 0 at a)
    //   probe 2  VC1  MEM_WR_RESP       b -> a   (answers that request; frees the slot)
    //   probe 3  VC2  ATTEST_CHALLENGE  a -> b
    // Exactly one packet is in the fabric per probe; each probe starts only when the
    // mesh is idle with every credit back, and ends after the mesh is idle again.
    //
    // Local loopback (a == b) is EXCLUDED unless HOP_INCLUDE_LOOPBACK is defined:
    // noc_router.sv a_no_loopback_local_sync (and the NOC_CROSSBAR X3 contract,
    // "a tile cannot send to itself") makes LOCAL->LOCAL an assertion error, which
    // the dual-lane judge rejects. The define is a diagnostic build, not registered.
    //
    // Timestamps (same definitions as N-8 / tb_noc_perf): cyc counts posedges since
    // reset release; t_inj = NI HEAD -> mesh handshake at the source; t_del =
    // destination completion: payload-last handshake (MAC off) or rx_mac_valid
    // (MAC on). A zero-payload packet (MEM_WR_RESP) with MAC off completes on its
    // HEAD_TAIL handshake (rx_payload_last is set on that flit). Latency = t_del - t_inj.
    // No latency value is assumed anywhere; every latency check is relative.
    //=========================================================================
`ifndef HOP_TRANSPORT_REV
`define HOP_TRANSPORT_REV "MF1-rev5"
`endif
`ifndef HOP_TOOL
`define HOP_TOOL "xsim-2024.1"
`endif
`ifdef HOP_INCLUDE_LOOPBACK
    localparam bit LOOPBACK = 1'b1;
`else
    localparam bit LOOPBACK = 1'b0;
`endif
    localparam string TRANSPORT = `HOP_TRANSPORT_REV;
    localparam string TOOL      = `HOP_TOOL;

    localparam int NVC    = 3;                                    // VC_REQUEST, VC_RESPONSE, VC_ATTESTATION
    localparam int MAXH   = int'(MESH_X) - 1 + int'(MESH_Y) - 1;  // 3 = largest XY distance in 3x2
    localparam int NPAIR  = LOOPBACK ? NT*NT : NT*(NT-1);         // 36 or 30 ordered pairs
    localparam int NPROBE = NPAIR*NVC;                            // 108 or 90
    localparam int MAXW   = 16;                                   // largest payload (ATTEST_RESPONSE), never sent here
    // Liveness bounds only (a probe that exceeds them fails its checks); they are
    // not latency expectations and no check compares a latency with them.
    localparam int SEND_BOUND = 256, DEL_BOUND = 512, DRAIN_BOUND = 512, QUIET = 16;

    int cyc, checks = 0, errors = 0;

    // ---- per-probe read-only monitor counters (cleared by clear_probe) ----
    bit mon_on;
    int inj_heads [NT], inj_flits [NT], ej_heads [NT], ej_flits [NT];
    int rx_heads  [NT], comp_n    [NT];
    int inj_cyc   [NT], comp_cyc  [NT], acc_cyc [NT];
    int full_cyc, stall_cyc, inj_stall_cyc, ej_stall_cyc, contain_n, txerr_n;
    coord_t                  c_src [NT], c_dst [NT];
    msg_type_e               c_msg [NT];
    logic [10:0]             c_ctl [NT];
    logic [4:0]              c_len [NT];
    int                      c_nw  [NT];
    logic [31:0]             c_words [NT][MAXW];
    logic [MAC_TAG_BITS-1:0] c_mac [NT];

    // ---- probe records (generator side; the only source of expectations) ----
    int np;
    int pr_src [NPROBE], pr_dst [NPROBE], pr_vc [NPROBE], pr_hops [NPROBE], pr_lat [NPROBE];
    bit pr_ok  [NPROBE];
    int cls_lat [NVC][MAXH+1];
    bit cls_present [NVC][MAXH+1];

    //-------------------------------------------------------------------------
    // Read-only probes (in addition to the scaffold's r_idle/l_idle).
    //-------------------------------------------------------------------------
    logic rq_idle [NT];                     // FIFOs, eject path, output locks idle
    logic cr_ok   [NT];                     // every credit counter back at depth 4
    logic [N_OUTSTANDING-1:0] slot_vec [NT];// NI outstanding-table valid bits
    logic [14:0] full_v [NT];               // 15 input-FIFO full flags (5 ports x 3 VCs)
    logic [NUM_PORTS-1:0] stall_v [NT];     // granted output suppressed by M9 (no credit)
    for (genvar g = 0; g < NT; g++) begin : GQ
        always_comb begin
            rq_idle[g] = !mesh.GEN_R[g].r.eject_wr_q &&
                          mesh.GEN_R[g].r.eject_empty &&
                         (mesh.GEN_R[g].r.u_allocator.output_locked == '0);
            for (int i = 0; i < NUM_PORTS * NUM_VC; i++)
                if (!mesh.GEN_R[g].r.fifo_empty[i]) rq_idle[g] = 1'b0;
            cr_ok[g] = 1'b1;
            for (int p = 0; p < NUM_PORTS; p++)
                for (int v = 0; v < NUM_VC; v++)
                    if (int'(mesh.GEN_R[g].r.u_credit_control.credit_count[p][v]) != 4)
                        cr_ok[g] = 1'b0;
        end
        assign slot_vec[g] = GN[g].ni.txn_valid_q;
        // noc_router exposes per-port/VC full flags only as named scalars.
        assign full_v[g] = {mesh.GEN_R[g].r.full_north_vc0, mesh.GEN_R[g].r.full_north_vc1, mesh.GEN_R[g].r.full_north_vc2,
                            mesh.GEN_R[g].r.full_south_vc0, mesh.GEN_R[g].r.full_south_vc1, mesh.GEN_R[g].r.full_south_vc2,
                            mesh.GEN_R[g].r.full_east_vc0,  mesh.GEN_R[g].r.full_east_vc1,  mesh.GEN_R[g].r.full_east_vc2,
                            mesh.GEN_R[g].r.full_west_vc0,  mesh.GEN_R[g].r.full_west_vc1,  mesh.GEN_R[g].r.full_west_vc2,
                            mesh.GEN_R[g].r.full_local_vc0, mesh.GEN_R[g].r.full_local_vc1, mesh.GEN_R[g].r.full_local_vc2};
        // M9 contract (noc_router.sv:61-66): grant_valid_qualified = grant_valid with credit.
        assign stall_v[g] = mesh.GEN_R[g].r.grant_valid & ~mesh.GEN_R[g].r.grant_valid_qualified;
    end

    //-------------------------------------------------------------------------
    // Generator-record functions (no DUT value is ever an expectation).
    //-------------------------------------------------------------------------
    function automatic int tile_x(input int i); return i % int'(MESH_X); endfunction   // index = y*3 + x
    function automatic int tile_y(input int i); return i / int'(MESH_X); endfunction
    function automatic int iabs(input int v); return v < 0 ? -v : v; endfunction
    function automatic int hops_of(input int s, input int d);
      return iabs(tile_x(s) - tile_x(d)) + iabs(tile_y(s) - tile_y(d));
    endfunction
    function automatic msg_type_e msg_of(input int vc);
      case (vc)
        0:       return MSG_MEM_WR_REQ;        // VC_REQUEST
        1:       return MSG_MEM_WR_RESP;       // VC_RESPONSE (answers the VC0 probe)
        default: return MSG_ATTEST_CHALLENGE;  // VC_ATTESTATION
      endcase
    endfunction
    // Control field. VC0: WSTRB=F, tag bit 0 = 0 (the NI overwrites it with the
    // allocated tag; after reset slot 0 is the lowest free slot, NI :212-228).
    // VC1: ERR=0, tag 0 (the tag of the request being answered). VC2: status=0xA.
    function automatic logic [10:0] ctl_of(input int vc);
      case (vc)
        0:       return 11'h780;
        1:       return 11'h000;
        default: return 11'h500;
      endcase
    endfunction
    function automatic logic [31:0] word_of(input int pid, input int s, input int d, input msg_type_e m, input int i);
      if (m == MSG_MEM_WR_REQ && i == 0)
        return REMOTE_BASE | (32'(d) << TILE_SEL_LSB) | (32'(pid) << 2);
      return {4'(s), 4'(d), 4'(int'(m)), 4'(i), 16'(pid*977 + 13)};
    endfunction
    function automatic logic [MAC_TAG_BITS-1:0] mac_of(input int pid);
      return {32'hA5000000 | 32'(pid), 32'h5A000000 | 32'(pid*3), ~32'(pid), (32'(pid) << 8) | 32'h000000C3};
    endfunction
    task automatic check(input bit ok, input string name);
      checks++; if (!ok) begin errors++; $display("[FAIL] %s", name); end
    endtask

    function automatic int sum6(input int a [NT]);
      int s; s = 0; for (int t = 0; t < NT; t++) s += a[t]; return s;
    endfunction
    function automatic bit mesh_idle();
      for (int t = 0; t < NT; t++) if (!rq_idle[t] || !l_idle[t] || tx_busy[t] || rx_busy[t]) return 0;
      return 1;
    endfunction
    function automatic bit credits_back();
      for (int t = 0; t < NT; t++) if (!cr_ok[t]) return 0;
      return 1;
    endfunction
    // Exactly slot 0 valid at tile `holder` (or nowhere when holder < 0).
    function automatic bit slots_expected(input int holder);
      for (int t = 0; t < NT; t++)
        if (slot_vec[t] !== ((t == holder) ? N_OUTSTANDING'(1) : N_OUTSTANDING'(0))) return 0;
      return 1;
    endfunction

    //-------------------------------------------------------------------------
    // Read-only monitor (posedge). cyc = posedges since the last reset release.
    //-------------------------------------------------------------------------
    always @(posedge clk) if (!rst) begin
      if (mon_on) begin
        for (int t = 0; t < NT; t++) begin
          if (tx_valid[t] && tx_ready[t]) acc_cyc[t] = cyc;
          if (m_in_valid[t] && m_in_ready[t]) begin
            inj_flits[t]++;
            if (m_in_flit[t].flit_type == FLIT_HEAD || m_in_flit[t].flit_type == FLIT_HEAD_TAIL) begin
              inj_heads[t]++; inj_cyc[t] = cyc;
            end
          end
          if (m_in_valid[t] && !m_in_ready[t]) inj_stall_cyc++;
          if (m_out_valid[t] && m_out_ready[t]) begin
            ej_flits[t]++;
            if (m_out_flit[t].flit_type == FLIT_HEAD || m_out_flit[t].flit_type == FLIT_HEAD_TAIL) ej_heads[t]++;
          end
          if (m_out_valid[t] && !m_out_ready[t]) ej_stall_cyc++;
          if (rx_hv[t] && rx_ready[t]) begin
            rx_heads[t]++;
            c_src[t] = rx_src[t]; c_dst[t] = rx_dst[t]; c_msg[t] = rx_msg[t];
            c_ctl[t] = rx_ctl[t]; c_len[t] = rx_len[t]; c_nw[t] = 0;
          end
          if (rx_pv[t] && rx_ready[t]) begin
            if (c_nw[t] < MAXW) c_words[t][c_nw[t]] = rx_pd[t];
            c_nw[t]++;
          end
          // Completion: trailing MAC (MAC on) or the payload-last / HEAD_TAIL handshake (MAC off).
          if (MAC_ENABLE ? rx_mv[t] : (rx_pl[t] && rx_ready[t] && (rx_pv[t] || rx_hv[t]))) begin
            comp_n[t]++; comp_cyc[t] = cyc;
            if (MAC_ENABLE) c_mac[t] = rx_mt[t];
          end
          if (rx_abort[t] || rx_perr[t] || rx_lerr[t]) contain_n++;
          if (tx_error[t]) txerr_n++;
          full_cyc  += $countones(full_v[t]);
          stall_cyc += $countones(stall_v[t]);
        end
      end
      cyc++;
    end

    //-------------------------------------------------------------------------
    // Sequencing.
    //-------------------------------------------------------------------------
    task automatic reset_mesh();
      @(negedge clk);
      rst = 1; mon_on = 0;
      for (int t = 0; t < NT; t++) begin
        tx_valid[t] = 0; tx_pvalid[t] = 0; tx_pdata[t] = '0; tx_dest[t] = '0; tx_msg[t] = MSG_MEM_WR_RESP;
        tx_control[t] = '0; tx_mac[t] = '0; rx_ready[t] = 1; st_clr[t] = 0;
      end
      repeat (5) @(negedge clk);
      rst = 0; cyc = 0;
    endtask

    task automatic clear_probe();
      mon_on = 1;
      full_cyc = 0; stall_cyc = 0; inj_stall_cyc = 0; ej_stall_cyc = 0; contain_n = 0; txerr_n = 0;
      for (int t = 0; t < NT; t++) begin
        inj_heads[t] = 0; inj_flits[t] = 0; ej_heads[t] = 0; ej_flits[t] = 0; rx_heads[t] = 0; comp_n[t] = 0;
        inj_cyc[t] = -1; comp_cyc[t] = -1; acc_cyc[t] = -1;
        c_src[t] = '0; c_dst[t] = '0; c_msg[t] = MSG_MEM_RD_REQ; c_ctl[t] = '0; c_len[t] = '0; c_nw[t] = 0; c_mac[t] = '0;
        for (int i = 0; i < MAXW; i++) c_words[t][i] = '0;
      end
    endtask

    // Tile-side send at tile s: request handshake, then the payload words (TX_FILL).
    task automatic send(input int s, input int d, input msg_type_e m, input logic [10:0] ctl, input int pid,
                        output bit sent);
      int n, w;
      n = int'(message_payload_flits(m)); sent = 1;
      @(negedge clk);
      tx_dest[s] = tile_to_coord(tile_id_e'(d)); tx_msg[s] = m; tx_control[s] = ctl;
      tx_mac[s] = mac_of(pid); tx_valid[s] = 1;
      w = 0;
      do begin @(posedge clk); w++; end while (!tx_ready[s] && w < SEND_BOUND);
      if (!tx_ready[s]) sent = 0;
      @(negedge clk); tx_valid[s] = 0;
      for (int i = 0; i < n && sent; i++) begin
        tx_pdata[s] = word_of(pid, s, d, m, i); tx_pvalid[s] = 1;
        w = 0;
        do begin @(posedge clk); w++; end while (!tx_pready[s] && w < SEND_BOUND);
        if (!tx_pready[s]) sent = 0;
        @(negedge clk);
      end
      tx_pvalid[s] = 0;
    endtask

    // One isolated probe: exactly one packet s -> d on VC vc; 6 checks, unconditionally.
    task automatic probe(input int s, input int d, input int vc);
      msg_type_e m; logic [10:0] ctl;
      int pid, nw, len, h, lat, w, pre_holder, post_holder;
      bit sent, pre, deliv, pay, other, idle, nocont;
      string id;
      pid = np; m = msg_of(vc); ctl = ctl_of(vc);
      nw  = int'(message_payload_flits(m));
      len = int'(message_length(m));            // 1 + payload + MAC_FLITS (NOC_PKG)
      h   = hops_of(s, d);
      // Slot state: the VC1 probe answers the VC0 request held by its destination.
      pre_holder  = (vc == 1) ? d : -1;
      post_holder = (vc == 0) ? s : -1;
      @(negedge clk);
      pre = mesh_idle() && credits_back() && slots_expected(pre_holder);
      clear_probe();
      send(s, d, m, ctl, pid, sent);
      w = 0; while (sum6(comp_n) == 0 && w < DEL_BOUND) begin @(negedge clk); w++; end
      w = 0; while (!(mesh_idle() && credits_back()) && w < DRAIN_BOUND) begin @(negedge clk); w++; end
      repeat (QUIET) @(negedge clk);
      mon_on = 0;
      deliv = sent && sum6(comp_n) == 1 && comp_n[d] == 1 && sum6(rx_heads) == 1 && rx_heads[d] == 1;
      pay = deliv && c_src[d] == tile_to_coord(tile_id_e'(s)) && c_dst[d] == tile_to_coord(tile_id_e'(d)) &&
            c_msg[d] == m && c_ctl[d] == ctl && c_len[d] == 5'(len) && c_nw[d] == nw &&
            (!MAC_ENABLE || c_mac[d] === mac_of(pid));
      for (int i = 0; i < nw && i < MAXW; i++) if (c_words[d][i] !== word_of(pid, s, d, m, i)) pay = 0;
      other = sum6(inj_heads) == 1 && inj_heads[s] == 1 && sum6(inj_flits) == len && inj_flits[s] == len &&
              sum6(ej_heads) == 1 && ej_heads[d] == 1 && sum6(ej_flits) == len && ej_flits[d] == len &&
              contain_n == 0 && txerr_n == 0;
      idle   = mesh_idle() && credits_back() && slots_expected(post_holder);
      nocont = full_cyc == 0 && stall_cyc == 0 && inj_stall_cyc == 0 && ej_stall_cyc == 0;
      lat = (deliv && inj_heads[s] == 1) ? comp_cyc[d] - inj_cyc[s] : -1;
      id = $sformatf("src=%0d dst=%0d vc=%0d mac=%0d", s, d, vc, MAC_ENABLE);
      // 6 probe checks (count independent of outcome).
      check(pre,    {"HOP_PRE_IDLE ", id});
      check(deliv,  {"HOP_DELIVERED_ONCE ", id});
      check(pay,    {"HOP_PAYLOAD ", id});
      check(other,  {"HOP_NO_OTHER_PACKET ", id});
      check(idle,   {"HOP_IDLE_AFTER ", id});
      check(nocont, {"HOP_NO_CONTENTION ", id});
      pr_src[np] = s; pr_dst[np] = d; pr_vc[np] = vc; pr_hops[np] = h; pr_lat[np] = lat;
      pr_ok[np] = pre && deliv && pay && other && idle && nocont && lat > 0;
      $display("HOP_PROBE id=%0d src=%0d dst=%0d vc=%0d msg=%0d hops=%0d flits=%0d t_inj=%0d t_del=%0d latency=%0d mac=%0d ok=%0d",
               pid, s, d, vc, int'(m), h, len, inj_cyc[s], comp_cyc[d], lat, MAC_ENABLE, pr_ok[np]);
      if (!nocont)
        $display("HOP_CONTENTION id=%0d fifo_full_port_cycles=%0d credit_stall_port_cycles=%0d inj_stall=%0d ej_stall=%0d",
                 pid, full_cyc, stall_cyc, inj_stall_cyc, ej_stall_cyc);
      np++;
    endtask

    initial begin
      int n, mn, mx, inc, prev;
      bit allok, det, mono, cinc, all_mono, all_cinc, cm;
      coord_t cc;
      string sum, zh;
      $display("CONFIG: TOP=tb_noc_hop_probes CASE=hop_probes transport=%s l2=none w=%0d wde=%0d n_out=%0d tool=%s MAC_FLITS=%0d CLOCK_NS=20 PAIRS=%0d PROBES=%0d CLASSES=%0d LOOPBACK=%0d",
               TRANSPORT, W, WDE, N_OUTSTANDING, TOOL, MAC_FLITS, NPAIR, NPROBE, NVC*(LOOPBACK ? MAXH+1 : MAXH), LOOPBACK);
      rst = 1; cyc = 0; np = 0; mon_on = 0;
      for (int t = 0; t < NT; t++) begin
        tx_valid[t] = 0; tx_pvalid[t] = 0; tx_pdata[t] = '0; tx_dest[t] = '0; tx_msg[t] = MSG_MEM_WR_RESP;
        tx_control[t] = '0; tx_mac[t] = '0; rx_ready[t] = 1; st_clr[t] = 0;
      end
      // 2 global checks.
      check(N_OUTSTANDING == 2, "CFG_N_OUTSTANDING");
      cm = 1;
      for (int t = 0; t < NT; t++) begin
        cc = tile_to_coord(tile_id_e'(t));
        if (int'(cc.x) != tile_x(t) || int'(cc.y) != tile_y(t)) cm = 0;
      end
      check(cm, "CFG_COORD_MAP");   // NOC_PKG tile_to_coord == index y*3+x used for hop counts
      // Probes: per ordered pair, fresh reset, then VC0 a->b, VC1 b->a, VC2 a->b.
      for (int a = 0; a < NT; a++)
        for (int b = 0; b < NT; b++) begin
          if (a == b && !LOOPBACK) continue;
          reset_mesh();
          probe(a, b, 0);
          probe(b, a, 1);
          probe(a, b, 2);
        end
      // Classes per (VC, hop count) in this MAC mode: zero-load determinism.
      for (int v = 0; v < NVC; v++)
        for (int hh = 0; hh <= MAXH; hh++) begin
          cls_lat[v][hh] = -1; cls_present[v][hh] = 0;
          n = 0; mn = 0; mx = 0; allok = 1;
          for (int i = 0; i < np; i++)
            if (pr_vc[i] == v && pr_hops[i] == hh) begin
              if (n == 0) begin mn = pr_lat[i]; mx = pr_lat[i]; end
              if (pr_lat[i] < mn) mn = pr_lat[i];
              if (pr_lat[i] > mx) mx = pr_lat[i];
              if (!pr_ok[i]) allok = 0;
              n++;
            end
          if (n == 0) continue;   // hop 0 exists only with HOP_INCLUDE_LOOPBACK (geometry, not outcome)
          cls_present[v][hh] = 1;
          det = allok && mn == mx && mn > 0;
          if (det) cls_lat[v][hh] = mn;
          check(det, $sformatf("HOP_CLASS_DETERMINISTIC vc=%0d hops=%0d mac=%0d", v, hh, MAC_ENABLE));
          $display("HOP_CLASS vc=%0d mac=%0d hops=%0d probes=%0d latency=%0d min=%0d max=%0d deterministic=%0d",
                   v, MAC_ENABLE, hh, n, cls_lat[v][hh], mn, mx, det);
        end
      // Per VC: strictly increasing with hop count; constant per-hop increment over hops 1..MAXH.
      all_mono = 1; all_cinc = 1; sum = "";
      for (int v = 0; v < NVC; v++) begin
        mono = 1; prev = -1;
        for (int hh = 0; hh <= MAXH; hh++)
          if (cls_present[v][hh]) begin
            if (cls_lat[v][hh] < 0) mono = 0;
            else if (prev >= 0 && cls_lat[v][hh] <= prev) mono = 0;
            prev = cls_lat[v][hh];
          end
        inc = (cls_lat[v][1] > 0 && cls_lat[v][2] > 0) ? cls_lat[v][2] - cls_lat[v][1] : -1;
        cinc = inc > 0;
        for (int hh = 2; hh <= MAXH; hh++)
          if (cls_lat[v][hh] < 0 || cls_lat[v][hh-1] < 0 || cls_lat[v][hh] - cls_lat[v][hh-1] != inc) cinc = 0;
        check(mono, $sformatf("HOP_MONOTONIC vc=%0d mac=%0d", v, MAC_ENABLE));
        check(cinc, $sformatf("HOP_CONST_INCREMENT vc=%0d mac=%0d", v, MAC_ENABLE));
        if (!mono) all_mono = 0;
        if (!cinc) all_cinc = 0;
        zh = "NA";
        if (LOOPBACK) zh = $sformatf("%0d", cls_lat[v][0]);
        sum = {sum, $sformatf(" vc%0d_per_hop=%0d vc%0d_hop1=%0d vc%0d_zero_hop=%s", v, inc, v, cls_lat[v][1], v, zh)};
      end
      $display("HOP_SUMMARY mac=%0d loopback=%0d%s monotonic=%0d const_increment=%0d", MAC_ENABLE, LOOPBACK, sum, all_mono, all_cinc);
      $display("CHECKS : %0d", checks); $display("ERRORS : %0d", errors); $display("RESULT : %s", errors == 0 ? "PASS" : "FAIL");
      $finish;
    end
    // Watchdog (no $fatal; the judge rejects TB_TIMEOUT). A clean run needs well under
    // 10,000 cycles; even if every probe ran into all of its liveness bounds
    // (90 x (6 x 256 + 512 + 512 + 16 + 6) < 240,000 cycles = 4.8 ms) the results
    // are printed before the watchdog. Registry tb_time_limit is 10 ms.
    initial begin #8ms; $display("TB_TIMEOUT hop probe bench (watchdog 8 ms)"); $finish; end
endmodule
